import { lazy, Suspense, type ReactNode } from "react";

export type ThemeName = "platform";

export const themeNames: ThemeName[] = ["platform"];

export type KcEnvName = "PLATFORM_ALLOW_PASSWORD" | "PLATFORM_SHARE_CLIENT_ID";

export const kcEnvNames: KcEnvName[] = ["PLATFORM_ALLOW_PASSWORD", "PLATFORM_SHARE_CLIENT_ID"];

